from __future__ import annotations

import http.client
import threading

import pytest

from linkvault.clock import Clock, parse_ts
from linkvault.server import make_server
from linkvault.store import Store

ADMIN_KEY = "admin-secret"


class Env:
    def __init__(self, tmp_path, rate_limit=60, fake=True, start="2026-01-01T00:00:10Z"):
        self.store = Store(str(tmp_path / "t.db"))
        self.clock = Clock(parse_ts(start) if fake else None)
        self.server = make_server(self.store, self.clock, ADMIN_KEY, rate_limit, fake, 0)
        self.port = self.server.server_address[1]
        self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)
        self.thread.start()

    def conn(self):
        return http.client.HTTPConnection("127.0.0.1", self.port, timeout=5)

    def request(self, method, path, body=None, headers=None, conn=None):
        c = conn or self.conn()
        c.request(method, path, body=body, headers=headers or {})
        r = c.getresponse()
        data = r.read()
        hdrs = {k.lower(): v for k, v in r.getheaders()}
        if conn is None:
            c.close()
        return r.status, hdrs, data

    def close(self):
        self.server.shutdown()
        self.server.server_close()
        self.store.close()


@pytest.fixture
def make_env(tmp_path):
    envs = []

    def factory(**kw):
        e = Env(tmp_path, **kw)
        envs.append(e)
        return e

    yield factory
    for e in envs:
        e.close()


@pytest.fixture
def env(make_env):
    return make_env()
