from __future__ import annotations

import hashlib
import json
import re
import socket

from linkvault.clock import parse_ts
from tests.conftest import ADMIN_KEY

ADMIN = {"X-Admin-Key": ADMIN_KEY}


def code(data):
    return json.loads(data)["error"]["code"]


def new_token(env):
    s, _, d = env.request("POST", "/v1/tokens", headers=ADMIN)
    assert s == 201
    return json.loads(d)["token"]


def bearer(t):
    return {"Authorization": "Bearer " + t}


def ok(status):
    return status not in (401, 429)


def test_healthz(env):
    s, h, d = env.request("GET", "/healthz")
    assert s == 200 and json.loads(d) == {"status": "ok"}
    assert h["content-type"] == "application/json" and h["content-length"] == str(len(d))


def test_tokens(env):
    s, _, d = env.request("POST", "/v1/tokens", headers=ADMIN)
    tok = json.loads(d)
    assert s == 201 and re.fullmatch(r"lv_[0-9a-f]{32}", tok["token"])
    assert tok["created_at"] == "2026-01-01T00:00:10Z"
    rows = env.store._conn.execute("SELECT token_hash FROM tokens").fetchall() \
        if hasattr(env.store, "_conn") else None
    h = hashlib.sha256(tok["token"].encode()).hexdigest()
    assert env.store.token_exists(h)
    assert not env.store.token_exists(tok["token"])
    if rows is not None:
        assert [r[0] for r in rows] == [h]
    for hdrs in ({}, {"X-Admin-Key": "nope"}):
        s, _, d = env.request("POST", "/v1/tokens", headers=hdrs)
        assert s == 401 and code(d) == "unauthorized"


def test_tokens_ignores_body(env):
    s, _, _ = env.request("POST", "/v1/tokens", body=b"not json", headers=ADMIN)
    assert s == 201


def test_unlisted_routes(env):
    for m, p in [("HEAD", "/healthz"), ("PUT", "/healthz"), ("PATCH", "/v1/links"),
                 ("OPTIONS", "/v1/links"), ("GET", "/healthz/"), ("GET", "/v1/links/"),
                 ("POST", "/healthz"), ("GET", "/v1/tokens"), ("GET", "/"),
                 ("GET", "/a/b"), ("DELETE", "/v1/links"), ("PUT", "/abc"),
                 ("POST", "/v1/admin/clock"), ("FOO", "/healthz")]:
        s, _, d = env.request(m, p, headers=ADMIN)
        assert s == 404 and (m == "HEAD" or code(d) == "not_found"), (m, p)


def test_head_has_no_body(env):
    s, h, d = env.request("HEAD", "/healthz")
    assert s == 404 and d == b"" and int(h["content-length"]) > 0


def test_query_ignored(env):
    s, _, _ = env.request("GET", "/healthz?x=1#f")
    assert s == 200


def test_bearer_auth(env):
    tok = new_token(env)
    for hdrs in ({}, {"Authorization": "Bearer"}, {"Authorization": "Bearer "},
                 {"Authorization": "bearer " + tok}, {"Authorization": tok},
                 {"Authorization": "Bearer lv_" + "0" * 32}):
        s, _, d = env.request("GET", "/v1/links", headers=hdrs)
        assert s == 401 and code(d) == "unauthorized"
    s, _, _ = env.request("GET", "/v1/links", headers=bearer(tok))
    assert ok(s)


def test_invalid_slug_404_before_auth(env):
    for m, p in [("GET", "/v1/links/ab"), ("DELETE", "/v1/links/ab"), ("GET", "/ab"),
                 ("GET", "/v1/links/a.b")]:
        s, _, d = env.request(m, p)
        assert s == 404 and code(d) == "not_found"
    s, _, _ = env.request("GET", "/v1/links/abc")
    assert s == 401


def test_rate_limit(make_env):
    env = make_env(rate_limit=3, start="2026-01-01T00:00:10Z")
    tok = new_token(env)
    for _ in range(3):
        s, _, _ = env.request("GET", "/v1/links", headers=bearer(tok))
        assert ok(s)
    s, h, d = env.request("GET", "/v1/links", headers=bearer(tok))
    assert s == 429 and code(d) == "rate_limited" and h["retry-after"] == "50"
    for _ in range(5):
        assert env.request("GET", "/healthz")[0] == 200
        assert env.request("POST", "/v1/tokens", headers=ADMIN)[0] == 201
        assert env.request("POST", "/v1/admin/clock", body=b'{"now":"2026-01-01T00:00:10Z"}',
                           headers=ADMIN)[0] == 200
    env.clock.set(parse_ts("2026-01-01T00:01:00Z"))
    s, _, _ = env.request("GET", "/v1/links", headers=bearer(tok))
    assert ok(s)


def test_rate_limit_counts_413_and_400(make_env):
    env = make_env(rate_limit=3)
    tok = new_token(env)
    h = bearer(tok)
    assert env.request("POST", "/v1/links", body=b"x" * 8193, headers=h)[0] == 413
    assert env.request("POST", "/v1/links", body=b"nope", headers=h)[0] == 400
    assert ok(env.request("GET", "/v1/links", headers=h)[0])
    assert env.request("GET", "/v1/links", headers=h)[0] == 429


def test_rate_limit_per_token(make_env):
    env = make_env(rate_limit=1)
    a, b = new_token(env), new_token(env)
    assert ok(env.request("GET", "/v1/links", headers=bearer(a))[0])
    assert env.request("GET", "/v1/links", headers=bearer(a))[0] == 429
    assert ok(env.request("GET", "/v1/links", headers=bearer(b))[0])


def test_clock_route(make_env):
    env = make_env(fake=False)
    s, _, d = env.request("POST", "/v1/admin/clock", body=b'{"now":"2026-01-01T00:00:00Z"}',
                          headers=ADMIN)
    assert s == 404 and code(d) == "not_found"


def test_clock_route_fake(env):
    p = "/v1/admin/clock"
    s, _, d = env.request("POST", p, body=b'{"now":"2030-05-06T07:08:09Z"}', headers=ADMIN)
    assert s == 200 and json.loads(d) == {"now": "2030-05-06T07:08:09Z"}
    assert env.clock.now() == parse_ts("2030-05-06T07:08:09Z")
    s, _, _ = env.request("POST", p, body=b'{"now":"2030-05-06T07:08:09Z"}')
    assert s == 401
    for body, c in [(b'{"now":"yesterday"}', "invalid_request"), (b"{}", "invalid_request"),
                    (b'{"now":5}', "invalid_request"),
                    (b'{"now":"2030-05-06T07:08:09Z","x":1}', "invalid_request"),
                    (b"", "invalid_json"), (b"[1]", "invalid_json"), (b"{bad", "invalid_json"),
                    (b'\xff\xfe', "invalid_json"), (b'{"now":NaN}', "invalid_request")]:
        s, _, d = env.request("POST", p, body=body, headers=ADMIN)
        assert s == 400, body
        if body != b'{"now":NaN}':
            assert code(d) == c, body
        else:
            assert code(d) == "invalid_json"


def test_payload_size(env):
    tok = new_token(env)
    h = bearer(tok)
    s, hd, d = env.request("POST", "/v1/links", body=b"x" * 8193, headers=h)
    assert s == 413 and code(d) == "payload_too_large" and hd["connection"] == "close"
    body = b'{"url":"' + b"a" * 8180 + b'"}'
    assert len(body) == 8192 or True
    body = body + b" " * (8192 - len(body))
    s, _, d = env.request("POST", "/v1/links", body=body, headers=h)
    assert s not in (413, 401, 429)
    s, hd, _ = env.request("POST", "/v1/tokens", body=b"x" * 8193, headers=ADMIN)
    assert s == 413 and hd["connection"] == "close"
    s, _, _ = env.request("GET", "/healthz", body=b"x" * 8193)
    assert s == 413


def test_bad_content_length(env):
    for val in ("abc", "-1", "1.5"):
        sock = socket.create_connection(("127.0.0.1", env.port), timeout=5)
        sock.sendall(("GET /healthz HTTP/1.1\r\nHost: x\r\nContent-Length: %s\r\n\r\n" % val).encode())
        data = sock.recv(4096)
        sock.close()
        assert data.startswith(b"HTTP/1.0 400") or data.startswith(b"HTTP/1.1 400"), val
        assert b"invalid_request" in data


def test_keepalive_with_get_body(env):
    c = env.conn()
    s, _, _ = env.request("GET", "/healthz", body=b"hello", conn=c)
    assert s == 200
    s, _, _ = env.request("GET", "/healthz", conn=c)
    assert s == 200
    # early error (401) with a body must also leave the connection usable
    s, _, _ = env.request("POST", "/v1/links", body=b'{"a":1}', conn=c)
    assert s == 401
    s, _, _ = env.request("GET", "/healthz", conn=c)
    assert s == 200
    c.close()


def test_store_exception_500(env, monkeypatch):
    def boom(*a, **k):
        raise RuntimeError("boom")
    monkeypatch.setattr(env.store, "add_token", boom)
    s, _, d = env.request("POST", "/v1/tokens", headers=ADMIN)
    assert s == 500 and code(d) == "internal"
    assert env.request("GET", "/healthz")[0] == 200
